/**
 * 提供盗贼／千面人原准备状态、活跃窗口与当夜提交证据的公开查询绑定。
 * 输入保留原 World／日期，输出为原准备结果、重入证据或关闭能力；不复制状态或授予行动。
 * 同步准入按调用点晚查询；实际开夜仍先检查准备状态，close 沿原 finally 顺序消费。
 * 查询不扩大读写权限；设置、资源和知识仍由 deal 生命周期拥有，本入口不重开已关闭的设置或行动窗口。
 */
export {
  hasActiveInitialIdentitySetup,
  hasActiveInitialIdentityNight,
  hasInitialIdentityNightCommit,
  initialIdentityKind,
  initialIdentitySetupReady,
  openInitialIdentityNight,
} from "./deal";

/** 开局组合使用同一准备类绑定；具体窗口仍拥有选择校验、提交与失败关闭。 */
export { InitialIdentitySetupWindow } from "./setup";

/** 开局整副牌组事实由具体owner完整构造；公共角色名单不含手牌映射或设置许可。 */
export { publishInitialIdentityDeal } from "./initial-deal-publication";

/**
 * 负责盗贼对共享初始身份库存、准备状态和选择投影的kind隔离。输入为原World、牌组／玩家或选择；
 * 输出原库存引用、脱离投影或原族错误，不把另一种已安装机制当成盗贼deal。
 * 唯一库存、发牌和提交仍归initial_identity；异族库存／投影返回undefined，布尔验证沿原false，ready为true，关闭／开夜不操作异族。
 * 先核安装kind再调用原共享方法，不以当前玩家角色标签重新分配权限，也不创建第二份库存。
 */
import { type World, type Role } from "../../../../core/domain";
import * as shared from "../initial_identity/deal";
export type ThiefCard = shared.InitialIdentityCard;
export type ThiefSlot = shared.InitialIdentitySlot;
export type ThiefSetupStatus = shared.InitialIdentitySetupStatus;
export type ThiefDeal = shared.InitialIdentityDeal;
// 安装kind来自同一共享owner；身份已换牌也不改本入口归属，不提前缓存World或共享查询。
const owns = (world: World) => shared.initialIdentityKind(world) === "thief";
export function installThiefDeal(
  world: World,
  roles: readonly Role[],
  playerIds: readonly number[],
): void {
  shared.installInitialIdentityDeal(world, roles, playerIds, "thief");
}
export const thiefDeal = (world: World): ThiefDeal | undefined =>
  owns(world) ? shared.initialIdentityStock(world) : undefined;
export const initialThiefDeal = (world: World): readonly Role[] | undefined =>
  owns(world) ? shared.initialIdentityDeal(world) : undefined;
export const thiefCandidateCounts = (world: World): ReadonlyMap<Role, number> | undefined =>
  owns(world) ? shared.initialIdentityCandidateCounts(world) : undefined;
export const thiefSetupStatus = (world: World): ThiefSetupStatus | undefined =>
  owns(world) ? shared.initialIdentitySetupStatus(world) : undefined;
export const hasActiveThiefSetup = (world: World): boolean =>
  owns(world) && shared.hasActiveInitialIdentitySetup(world);
export const thiefSetupReady = (world: World): boolean =>
  !owns(world) || shared.initialIdentitySetupReady(world);
export const pendingThiefDealValid = (world: World): boolean =>
  owns(world) && shared.pendingInitialIdentityDealValid(world);
/** 错族先给原盗贼错误；只有本族才进入共享open和其原重入／状态检查，失败不补开窗口。 */
export function openThiefSetup(world: World): ThiefDeal {
  if (!owns(world)) throw new Error("thief_setup_unavailable");
  return shared.openInitialIdentitySetup(world);
}
export function closeThiefSetup(world: World, status: Exclude<ThiefSetupStatus, "pending">): void {
  if (owns(world)) shared.closeInitialIdentitySetup(world, status);
}
export function selectThiefCard(world: World, actorId: number, slot: ThiefSlot | null): Role {
  if (!owns(world)) throw new Error("thief_selection_unavailable");
  return shared.selectInitialIdentityCard(world, actorId, slot);
}
/** 先kind隔离，再读共享投影；保原新外层对象及共享selection副本，不披露异族牌面或新授选择。 */
export function projectThiefSetup(world: World) {
  if (!owns(world)) return;
  const data = shared.projectInitialIdentitySetup(world);
  return data ? { ...data, policy: shared.INITIAL_IDENTITY_POLICIES.thief } : undefined;
}
export const hasActiveThiefNight = (world: World): boolean =>
  owns(world) && shared.hasActiveInitialIdentityNight(world);
export const hasThiefNightCommit = (world: World, day: number): boolean =>
  owns(world) && shared.hasInitialIdentityNightCommit(world, day);
export function openThiefNight(world: World, day: number): () => void {
  return owns(world) ? shared.openInitialIdentityNight(world, day) : () => {};
}

/**
 * 负责盗贼对共享初始身份 scope 和选择查询的本族接线；输入为原参与者与请求，输出保留原绑定。
 * 生命周期、库存及选择提交仍由共享所有者复验；请求别名统一走公共传播入口，不以查询或构造依赖授予许可。
 * 包装类构造时才读取 shared 类，并透传同一惰性依赖；请求工厂仍在共享窗口原执行点创建，异常原样传播。
 */
import type { World, ActionRequest, Phase, GameEvent } from "../../../../core/domain";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import type { ActionRequestFactoryConstructorPort } from "../../../../core/domain/actions";
import * as shared from "../initial_identity/setup";
export type ThiefScope = shared.InitialIdentityScope;
export const authorizedThiefScope = (
  world: World,
  actorId: number,
  day: number | undefined,
  phase: Phase,
  scope: object | undefined,
) => shared.authorizedInitialIdentityScope(world, actorId, day, phase, scope, "thief");
/** 先让共享请求绑定检查原体／context，再按kind返回原scope；查询不接受行动或续期权限。 */
export const thiefRequestScope = (world: World, r: ActionRequest) => {
  const s = shared.initialIdentityRequestScope(world, r);
  return s?.kind === "thief" ? s : undefined;
};
/** 共享owner核actor／kind／当前性后，旧盗贼视图只保required与同一cards数组；不另公开allowedSlots。 */
export function projectThiefChoices(world: World, actorId: number) {
  const s = shared.initialIdentityRequestChoices(world, actorId, "thief");
  return s ? { required: s.mustChoose, cards: s.cards } : undefined;
}
/** Catalog可在共享setup求值中导入；原new点才读取shared类，保参数／惰性依赖原引用，不在顶层捕获构造器。 */
export class ThiefSetupWindow {
  private readonly window: shared.InitialIdentitySetupWindow;
  constructor(
    world: World,
    gateway: ToolGateway,
    events: GameEvent[],
    construction: { readonly requestFactory: ActionRequestFactoryConstructorPort },
  ) {
    this.window = new shared.InitialIdentitySetupWindow(world, gateway, events, "thief", construction);
  }
  execute(...args: Parameters<shared.InitialIdentitySetupWindow["execute"]>): Promise<boolean> {
    return this.window.execute(...args);
  }
}

/**
 * 负责千面人对共享实体牌库存、准备状态与选择投影的kind边界。输入为原World、牌组／玩家或slot；
 * 输出本族原引用、选择副本或原拒绝，异族查询不披露库存，ready沿原true及关闭／开夜no-op。
 * 库存与物理换牌只归initial_identity；本入口保先kind后共享调用、原错误前缀及选择slot限制。
 * 显示投影不授予换牌或生命权限，不合并盗贼可保留身份与千面人必须选牌两种政策。
 */
import { type World, type Role } from "../../../../core/domain";
import * as shared from "../initial_identity/deal";
export type ShapeshifterCard = shared.InitialIdentityCard;
export type ShapeshifterSlot = shared.InitialIdentitySlot;
export type ShapeshifterSetupStatus = shared.InitialIdentitySetupStatus;
export type ShapeshifterDeal = shared.InitialIdentityDeal;
// 只按共享owner已安装kind隔离；不从已换牌后的live角色或玩家知识推断本族许可。
const owns = (world: World) => shared.initialIdentityKind(world) === "shapeshifter";
export function installShapeshifterDeal(
  world: World,
  roles: readonly Role[],
  playerIds: readonly number[],
): void {
  shared.installInitialIdentityDeal(world, roles, playerIds, "shapeshifter");
}
export const shapeshifterDeal = (world: World): ShapeshifterDeal | undefined =>
  owns(world) ? shared.initialIdentityStock(world) : undefined;
export const initialShapeshifterDeal = (world: World): readonly Role[] | undefined =>
  owns(world) ? shared.initialIdentityDeal(world) : undefined;
export const shapeshifterCandidateCounts = (world: World): ReadonlyMap<Role, number> | undefined =>
  owns(world) ? shared.initialIdentityCandidateCounts(world) : undefined;
export const shapeshifterSetupStatus = (world: World): ShapeshifterSetupStatus | undefined =>
  owns(world) ? shared.initialIdentitySetupStatus(world) : undefined;
export const hasActiveShapeshifterSetup = (world: World): boolean =>
  owns(world) && shared.hasActiveInitialIdentitySetup(world);
export const shapeshifterSetupReady = (world: World): boolean =>
  !owns(world) || shared.initialIdentitySetupReady(world);
export const pendingShapeshifterDealValid = (world: World): boolean =>
  owns(world) && shared.pendingInitialIdentityDealValid(world);
export function openShapeshifterSetup(world: World): ShapeshifterDeal {
  if (!owns(world)) throw new Error("shapeshifter_setup_unavailable");
  return shared.openInitialIdentitySetup(world);
}
export function closeShapeshifterSetup(
  world: World,
  status: Exclude<ShapeshifterSetupStatus, "pending">,
): void {
  if (owns(world)) shared.closeInitialIdentitySetup(world, status);
}
export function selectShapeshifterCard(
  world: World,
  actorId: number,
  slot: ShapeshifterSlot,
): Role {
  if (!owns(world)) throw new Error("shapeshifter_selection_unavailable");
  return shared.selectInitialIdentityCard(world, actorId, slot);
}
/** 先kind与完整共享投影，再核null slot并重建selection；不提前复制／读选择或放宽千面人的原拒绝。 */
export function projectShapeshifterSetup(world: World) {
  if (!owns(world)) return;
  const data = shared.projectInitialIdentitySetup(world);
  if (!data) return;
  const selection = data.selection;
  if (selection?.slot === null) throw new Error("shapeshifter_selection_invalid");
  return {
    ...data,
    policy: shared.INITIAL_IDENTITY_POLICIES.shapeshifter,
    selection: selection ? { ...selection, slot: selection.slot } : null,
  };
}
export const hasActiveShapeshifterNight = (world: World): boolean =>
  owns(world) && shared.hasActiveInitialIdentityNight(world);
export const hasShapeshifterNightCommit = (world: World, day: number): boolean =>
  owns(world) && shared.hasInitialIdentityNightCommit(world, day);
export function openShapeshifterNight(world: World, day: number): () => void {
  return owns(world) ? shared.openInitialIdentityNight(world, day) : () => {};
}

/**
 * 负责千面人对共享初始身份 scope 和选择查询的本族接线；输入为原参与者与请求，输出保留原绑定。
 * 生命周期、库存及选择提交仍由共享所有者复验；请求别名统一走公共传播入口，不以查询或构造依赖授予许可。
 * 包装类构造时才读取 shared 类，并透传同一惰性依赖；请求工厂仍在共享窗口原执行点创建，异常原样传播。
 */
import type { World, ActionRequest, Phase, GameEvent } from "../../../../core/domain";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import type { ActionRequestFactoryConstructorPort } from "../../../../core/domain/actions";
import * as shared from "../initial_identity/setup";
export type ShapeshifterScope = shared.InitialIdentityScope;
export const authorizedShapeshifterScope = (
  world: World,
  actorId: number,
  day: number | undefined,
  phase: Phase,
  scope: object | undefined,
) => shared.authorizedInitialIdentityScope(world, actorId, day, phase, scope, "shapeshifter");
/** 先让共享请求绑定检查原体／context，再按kind返回原scope；查询不接受行动或续期权限。 */
export const shapeshifterRequestScope = (world: World, r: ActionRequest) => {
  const s = shared.initialIdentityRequestScope(world, r);
  return s?.kind === "shapeshifter" ? s : undefined;
};
/** 返回原共享选择对象，保mustChoose／allowedSlots／cards形状；不照盗贼裁剪或重新推导必选政策。 */
export function projectShapeshifterChoices(world: World, actorId: number) {
  const s = shared.initialIdentityRequestChoices(world, actorId, "shapeshifter");
  return s;
}
/** Catalog可在共享setup求值中导入；原new点才读取shared类，保参数／惰性依赖原引用，不在顶层捕获构造器。 */
export class ShapeshifterSetupWindow {
  private readonly window: shared.InitialIdentitySetupWindow;
  constructor(
    world: World,
    gateway: ToolGateway,
    events: GameEvent[],
    construction: { readonly requestFactory: ActionRequestFactoryConstructorPort },
  ) {
    this.window = new shared.InitialIdentitySetupWindow(world, gateway, events, "shapeshifter", construction);
  }
  execute(...args: Parameters<shared.InitialIdentitySetupWindow["execute"]>): Promise<boolean> {
    return this.window.execute(...args);
  }
}

